class MigrationRunner
{
    // Breaking change: EF Core 9 now manages its own transactions during Migrate().
    // Wrapping in a user transaction throws. Remove the explicit transaction.
    void ApplyMigrations(AppDbContext db)
    {
        db.Database.Migrate();
    }
}

