using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "AppDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed the default discriminator from
        // "Discriminator" to "$type". Existing documents use "Discriminator",
        // so we must explicitly preserve the old property name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 no longer embeds the discriminator in the
        // JSON "id" property. Existing documents have id = "Session|<key>".
        // Preserve the old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Breaking change 3: Sync I/O (ToList, SaveChanges, etc.) on the Cosmos DB
    // provider now throws in EF Core 9. Must use async equivalents.
    public async Task<List<Session>> GetSessionsAsync()
    {
        // Before (throws in EF Core 9):
        //   return _db.Sessions.ToList();
        return await _db.Sessions.ToListAsync();
    }

    public async Task SaveSessionAsync(Session session)
    {
        // Before (throws in EF Core 9):
        //   _db.Sessions.Add(session);
        //   _db.SaveChanges();
        _db.Sessions.Add(session);
        await _db.SaveChangesAsync();
    }
}

